//! Dataops P32: multimodal ingestion, lineage, and quality-control integrity.
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::{json,Value};
use std::collections::BTreeSet;
use thiserror::Error;
pub const BOUNDARY:&str=PRECLINICAL_BOUNDARY;pub const CONTENT_TYPE:&str="application/vnd.aurora.dataops.ingestion-integrity-card-1+json";
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct DataAsset4{pub asset_id:String,pub modality:String,pub dimensions:String,pub unit:String,pub ontology:String,pub qc_score_milli:u16,pub qc_threshold_milli:u16,pub lineage_digest:String,pub checksum:String,pub evidence_state:String,pub negative_result:bool,pub local:bool,pub aggregate_only:bool}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct IngestionIntegrityRequest4{pub schema_version:String,pub request_id:String,pub purpose:String,pub assets:Vec<DataAsset4>,pub required_asset_order:Vec<String>,pub required_modality_order:Vec<String>,pub replay_identity:String,pub policy_allowed:bool,pub protected_closure:bool,pub signed_manifest:bool,pub raw_data_local:bool,pub aggregate_only:bool,pub adversarial_events:Vec<String>,pub asset_budget:usize,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct IngestionIntegrityArtifact4{pub artifact_id:String,pub content_type:String,pub content_hash:String,pub semantic_loss:Vec<String>,pub evidence_digests:Vec<String>,pub boundary:String}
#[derive(Debug,Clone,Serialize,Deserialize,PartialEq,Eq)] pub struct IngestionIntegrityCard7{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub purpose:String,pub disposition:String,pub asset_order:Vec<String>,pub accepted_order:Vec<String>,pub rejected_order:Vec<String>,pub unknown_order:Vec<String>,pub omitted_order:Vec<String>,pub modality_order:Vec<String>,pub dimension_order:Vec<String>,pub ontology_order:Vec<String>,pub qc_order:Vec<String>,pub lineage_order:Vec<String>,pub negative_order:Vec<String>,pub replay_identity:String,pub closure_digest:String,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String,pub effect_receipts:Vec<String>,pub artifact:IngestionIntegrityArtifact4}
#[derive(Debug,Error)] pub enum IngestionIntegrityError{#[error("ingestion integrity input is invalid: {0}")] Invalid(String),#[error("ingestion integrity digest failed: {0}")] Digest(String)}
fn digest(v:&str)->bool{v.len()==64&&v.bytes().all(|b|b.is_ascii_hexdigit())}fn canonical(v:&[String])->bool{v.windows(2).all(|w|w[0]<w[1])}fn invalid(v:impl Into<String>)->IngestionIntegrityError{IngestionIntegrityError::Invalid(v.into())}
pub fn manifest(feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":contract_version,"owner_crate":"dataops","consumers":["ingestion gateway","QC workbench","lineage ledger","federation admission"],"behavior":format!("qualify typed multimodal ingestion at {scale} ({mode})"),"value":"prevents low-quality, unlineaged, semantically incompatible, or non-local assets from entering research workflows","input_schema":"IngestionIntegrityRequest4@1","output_schema":"IngestionIntegrityCard7@1","effects":["emit:ingestion-card","retain:lineage-witness","block:unsafe-asset"],"permissions":["read:local-asset-metadata"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":BOUNDARY})}
fn validate_card(c:&IngestionIntegrityCard7)->Result<(),IngestionIntegrityError>{if c.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||c.feature_id.is_empty()||c.boundary!=BOUNDARY||c.artifact.boundary!=BOUNDARY||!c.raw_data_local||!c.aggregate_only||!digest(&c.replay_identity)||!digest(&c.closure_digest)||c.artifact.content_type!=CONTENT_TYPE||c.artifact.content_hash!=c.closure_digest{return Err(invalid("ingestion identity, locality, artifact, digest, or boundary is incomplete"));}for v in [&c.asset_order,&c.accepted_order,&c.rejected_order,&c.unknown_order,&c.omitted_order,&c.modality_order,&c.dimension_order,&c.ontology_order,&c.qc_order,&c.lineage_order,&c.negative_order,&c.effect_receipts]{if !canonical(v){return Err(invalid("ingestion vectors are not canonical"));}}let ids=c.asset_order.iter().collect::<BTreeSet<_>>();let states=c.accepted_order.iter().chain(&c.rejected_order).chain(&c.unknown_order).chain(&c.omitted_order).collect::<Vec<_>>();if states.len()!=ids.len()||states.into_iter().collect::<BTreeSet<_>>()!=ids{return Err(invalid("asset states do not partition assets"));}Ok(())}
pub fn qualify(q:&IngestionIntegrityRequest4,feature_id:&str,contract_version:&str,scale:&str,mode:&str)->Result<IngestionIntegrityCard7,IngestionIntegrityError>{if q.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||q.request_id.trim().is_empty()||q.purpose.trim().is_empty()||q.assets.is_empty()||q.required_asset_order.is_empty()||!canonical(&q.required_asset_order)||!canonical(&q.required_modality_order)||!digest(&q.replay_identity)||q.boundary!=BOUNDARY||!q.raw_data_local||!q.aggregate_only||!canonical(&q.adversarial_events)||q.asset_budget==0{return Err(invalid("ingestion identity, ordering, digest, locality, boundary, or budget is invalid"));}let mut rows=q.assets.clone();rows.sort_by(|a,b|a.asset_id.cmp(&b.asset_id));let mut seen=BTreeSet::new();let mut accepted=BTreeSet::new();let mut rejected=BTreeSet::new();let mut unknown=BTreeSet::new();let mut omitted=BTreeSet::new();let mut modalities=BTreeSet::new();let mut dimensions=BTreeSet::new();let mut ontologies=BTreeSet::new();let mut qc=BTreeSet::new();let mut lineage=BTreeSet::new();let mut negative=BTreeSet::new();let mut evidence=BTreeSet::new();for a in &rows{if a.asset_id.trim().is_empty()||!seen.insert(a.asset_id.clone())||a.modality.trim().is_empty()||a.dimensions.trim().is_empty()||a.unit.trim().is_empty()||a.ontology.trim().is_empty()||!digest(&a.lineage_digest)||!digest(&a.checksum)||a.evidence_state.trim().is_empty()||!a.local||!a.aggregate_only{return Err(invalid("asset identity, dimensions, ontology, digest, evidence, or locality is invalid"));}modalities.insert(format!("{}:{}",a.asset_id,a.modality));dimensions.insert(format!("{}:{}",a.asset_id,a.dimensions));ontologies.insert(format!("{}:{}",a.asset_id,a.ontology));qc.insert(format!("{}:{}",a.asset_id,a.qc_score_milli));lineage.insert(format!("{}:{}",a.asset_id,a.lineage_digest));evidence.insert(a.checksum.clone());if a.negative_result{negative.insert(format!("{}:negative-result",a.asset_id));}if a.evidence_state=="unknown"||a.lineage_digest==q.replay_identity{unknown.insert(a.asset_id.clone());}else if a.qc_score_milli<a.qc_threshold_milli||a.ontology=="unknown"{rejected.insert(a.asset_id.clone());}else if !q.required_asset_order.contains(&a.asset_id){omitted.insert(a.asset_id.clone());}else{accepted.insert(a.asset_id.clone());}}let missing=q.required_asset_order.iter().filter(|x|!seen.contains(*x)).cloned().collect::<Vec<_>>();let global=!q.policy_allowed||!q.protected_closure||!q.signed_manifest||!q.raw_data_local||!q.aggregate_only||!q.adversarial_events.is_empty()||rows.len()>q.asset_budget;if global{omitted.extend(seen.iter().cloned());accepted.clear();rejected.clear();unknown.clear();}let disposition=if global{"blocked"}else if !missing.is_empty()||!unknown.is_empty(){"unknown"}else if !rejected.is_empty()||!omitted.is_empty(){"partial"}else{"qualified"};let asset_order=seen.iter().cloned().collect::<Vec<_>>();let accepted_order=accepted.into_iter().collect::<Vec<_>>();let rejected_order=rejected.into_iter().collect::<Vec<_>>();let unknown_order=unknown.into_iter().collect::<Vec<_>>();let omitted_order=omitted.into_iter().collect::<Vec<_>>();let body=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":contract_version,"feature_id":feature_id,"request_id":q.request_id,"purpose":q.purpose,"disposition":disposition,"asset_order":asset_order,"accepted_order":accepted_order,"rejected_order":rejected_order,"unknown_order":unknown_order,"omitted_order":omitted_order,"modality_order":modalities.into_iter().collect::<Vec<_>>(),"dimension_order":dimensions.into_iter().collect::<Vec<_>>(),"ontology_order":ontologies.into_iter().collect::<Vec<_>>(),"qc_order":qc.into_iter().collect::<Vec<_>>(),"lineage_order":lineage.into_iter().collect::<Vec<_>>(),"negative_order":negative.into_iter().collect::<Vec<_>>(),"replay_identity":q.replay_identity,"raw_data_local":true,"aggregate_only":true,"boundary":BOUNDARY});let closure_digest=ContentHash::of_value(&body).map_err(|e|IngestionIntegrityError::Digest(e.to_string()))?.to_string();let effect_receipts=if disposition=="qualified"{vec![format!("approve:ingestion:{}",q.request_id)]}else{vec!["block:unsafe-asset".into()]};let artifact=IngestionIntegrityArtifact4{artifact_id:format!("dataops-ingestion:{}",q.request_id),content_type:CONTENT_TYPE.into(),content_hash:closure_digest.clone(),semantic_loss:body["omitted_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),evidence_digests:evidence.into_iter().collect(),boundary:BOUNDARY.into()};let c=IngestionIntegrityCard7{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:contract_version.into(),feature_id:feature_id.into(),request_id:q.request_id.clone(),purpose:q.purpose.clone(),disposition:disposition.into(),asset_order:body["asset_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),accepted_order,rejected_order,unknown_order,omitted_order,modality_order:body["modality_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),dimension_order:body["dimension_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),ontology_order:body["ontology_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),qc_order:body["qc_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),lineage_order:body["lineage_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),negative_order:body["negative_order"].as_array().unwrap().iter().filter_map(Value::as_str).map(str::to_owned).collect(),replay_identity:q.replay_identity.clone(),closure_digest,raw_data_local:true,aggregate_only:true,boundary:BOUNDARY.into(),effect_receipts,artifact};let _=(scale,mode);validate_card(&c)?;Ok(c)}
